Account.ready.then(async user=>{
 if(user.role!=='admin'){location.replace('/sets.html');return;}
 const $=id=>document.getElementById(id);
 function badge(id,n,label){$(id).textContent=n+' '+label;$(id).classList.toggle('clear',n===0)}
 function backupStatus(x){const ok=!!(x.verified&&x.created);$('backup-title').textContent=ok?'Backup verified':'Backup needed';$('backup-icon').textContent=ok?'✓':'!';$('backup-icon').classList.toggle('verified',ok);$('home-backup-status').textContent=ok?'Last verified backup: '+new Date(x.created).toLocaleString()+'. '+x.questions+' questions. Saved on this computer.':'No verified backup recorded. Create one now.';}
 const checks=[['/api/questions',x=>{$('total-questions').textContent=x.length;const box=$('publication-summary');box.replaceChildren();for(const status of ['Published','Reviewed','Draft','Archived']){const n=x.filter(q=>q.status===status).length;if(n||status==='Published'){const p=document.createElement('span');p.textContent=status+' '+n;if(status==='Published')p.className='published';box.append(p)}}}],['/api/admin/users',x=>$('active-learners').textContent=x.filter(u=>u.role==='learner'&&!u.disabled).length],['/api/admin/dashboard?mode=exam',x=>$('completed-exams').textContent=x.summary.completed],['/api/admin/feedback',x=>{const n=x.filter(f=>f.status!=='Resolved').length;$('feedback-count').textContent=n;badge('feedback-open',n,'open')}],['/api/backup-status',backupStatus],['/api/admin/editor-proposals',x=>badge('proposal-count',x.filter(p=>p.status==='Pending').length,'pending')]];
 const results=await Promise.allSettled(checks.map(async([path,show])=>show(await Account.request(path))));
 $('home-status').textContent=results.some(x=>x.status==='rejected')?'Some overview data could not load. Refresh to try again.':'';
 if(results[4].status==='rejected'){$('backup-title').textContent='Backup status unavailable';$('home-backup-status').textContent='Could not load backup status.';}
 if(results[5].status==='rejected')$('proposal-count').textContent='Unavailable';if(results[3].status==='rejected')$('feedback-open').textContent='Unavailable';
 $('home-backup').onclick=async()=>{const button=$('home-backup');button.disabled=true;$('backup-title').textContent='Backing up…';$('backup-icon').classList.remove('verified');$('backup-icon').textContent='…';$('home-backup-status').textContent='Creating and verifying backup…';try{backupStatus(await Account.request('/api/backup',{}))}catch(e){$('backup-title').textContent='Backup failed';$('backup-icon').textContent='!';$('home-backup-status').textContent=e.message}finally{button.disabled=false}};
}).catch(()=>{});
